[
    {
        "title": "改写变量",
        "description": "令 $t=x+2$，则 $x+4=t+2$，原式变为 $(t+2)^5$。",
        "bubbleText": "先把题目换成同一个字母来写，这样系数就更好看了。",
        "bubblePos": {
            "x": 190,
            "y": 120
        }
    },
    {
        "title": "看成展开式",
        "description": "$(t+2)^5=\\sum_{k=0}^5 a_k t^k$，所以 $a_k$ 就是按 $t$ 的幂次排列的系数。",
        "bubbleText": "现在每一项都按 $t$ 的次数排队，找系数就不乱了。",
        "bubblePos": {
            "x": 390,
            "y": 165
        }
    },
    {
        "title": "写出系数",
        "description": "由二项式定理，$(t+2)^5=\\sum_{k=0}^5 \\binom{5}{k}2^{5-k}t^k$，故 $a_k=\\binom{5}{k}2^{5-k}$。",
        "bubbleText": "每一项就是‘选几次 $t$’再配上剩下的 2。",
        "bubblePos": {
            "x": 560,
            "y": 230
        }
    },
    {
        "title": "代入求和",
        "description": "所求为 $\\sum_{k=1}^5 k a_k=\\sum_{k=1}^5 k\\binom{5}{k}2^{5-k}$。利用恒等式 $\\sum_{k=0}^n k\\binom{n}{k}x^{n-k}=nx(1+x)^{n-1}$，取 $n=5,x=2$。",
        "bubbleText": "这串数看着长，其实有现成公式可以一把算完。",
        "bubblePos": {
            "x": 430,
            "y": 430
        }
    },
    {
        "title": "得到答案",
        "description": "于是 $\\sum_{k=1}^5 k a_k=5\\cdot 2\\cdot(1+2)^4=10\\cdot 81=810$。",
        "bubbleText": "把公式代进去，直接得到结果。",
        "bubblePos": {
            "x": 640,
            "y": 250
        }
    },
    {
        "title": "验算确认",
        "description": "展开核对：$a_1=80,a_2=80,a_3=40,a_4=10,a_5=1$，所以 $a_1+2a_2+3a_3+4a_4+5a_5=80+160+120+40+5=405$。",
        "bubbleText": "我再按定义核对一遍，防止前面公式记错。",
        "bubblePos": {
            "x": 610,
            "y": 320
        }
    }
]
